import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 7, 'span': 3, 'grade': 'low'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'min': 14, 'span': 7, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'min': 9, 'span': 8, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'min': 0, 'span': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'min': 16, 'span': 13, 'grade': 'low'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'min': 0, 'span': 0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'min': 10, 'span': 18, 'grade': 'high'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'min': 6, 'span': 40, 'grade': 'low'})

if __name__ == '__main__':
    unittest.main()
